def try_resolve(repo, **kw):
    "`resolve(repo)`, or None (logged) when it cannot be had, e.g. offline."
    try: return resolve(repo, **kw)
    except Exception as e: log.warning(f'laghu: {repo} unavailable: {e!r}'); return None

